import pandas as pd
import numpy as np
import json
from datetime import datetime
import base64
import io
import matplotlib.pyplot as plt
import seaborn as sns

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# --- Calculations ---
total_books = len(df)
unique_books = df['Name'].nunique()
genre_split = df['Genre'].value_counts()
avg_price = df['Price'].mean()
avg_rating = df['User Rating'].mean()
avg_reviews = df['Reviews'].mean()

# Price vs Rating correlation
correlation = df['Price'].corr(df['User Rating'])

# Genre Comparison
genre_stats = df.groupby('Genre').agg({
    'Price': 'mean',
    'User Rating': 'mean',
    'Reviews': 'mean',
    'Name': 'count'
}).reset_index()

# Temporal Trends
yearly_stats = df.groupby('Year').agg({
    'Price': 'mean',
    'User Rating': 'mean',
    'Reviews': 'mean'
}).reset_index()

yearly_genre = df.groupby(['Year', 'Genre']).size().unstack(fill_value=0).reset_index()

# Top Authors
top_authors = df['Author'].value_counts().head(10).reset_index()
top_authors.columns = ['Author', 'Frequency']
top_authors_stats = df[df['Author'].isin(top_authors['Author'])].groupby('Author').agg({
    'Price': 'mean',
    'User Rating': 'mean'
}).reset_index()
top_authors = top_authors.merge(top_authors_stats, on='Author').sort_values('Frequency', ascending=False)

# --- Visualizations (Base64) ---
def get_base64_image(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    img_str = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return f"data:image/png;base64,{img_str}"

# 1. Scatter Plot: Price vs Rating
fig, ax = plt.subplots(figsize=(8, 5))
sns.scatterplot(data=df, x='Price', y='User Rating', hue='Genre', alpha=0.6, ax=ax)
ax.set_title('Price vs. User Rating')
scatter_img = get_base64_image(fig)

# 2. Line Chart: Temporal Trends
fig, ax1 = plt.subplots(figsize=(10, 5))
ax2 = ax1.twinx()
ax1.plot(yearly_stats['Year'], yearly_stats['Price'], color='blue', marker='o', label='Avg Price')
ax2.plot(yearly_stats['Year'], yearly_stats['User Rating'], color='orange', marker='s', label='Avg Rating')
ax1.set_xlabel('Year')
ax1.set_ylabel('Average Price ($)', color='blue')
ax2.set_ylabel('Average Rating', color='orange')
ax1.set_xticks(yearly_stats['Year'])
fig.legend(loc="upper right", bbox_to_anchor=(0.9, 0.9))
ax1.set_title('Year-over-Year Trends: Price and Rating')
trends_img = get_base64_image(fig)

# 3. Bar Chart: Genre Comparison
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(10, 4))
sns.barplot(data=genre_stats, x='Genre', y='Price', ax=ax1, palette='Set2')
ax1.set_title('Average Price by Genre')
sns.barplot(data=genre_stats, x='Genre', y='User Rating', ax=ax2, palette='Set2')
ax2.set_ylim(4.0, 5.0)
ax2.set_title('Average Rating by Genre')
genre_img = get_base64_image(fig)


# --- HTML Generation ---

css = """
