        border-radius: 4px;
        padding: 10px;
    }
    .recommendations li {
        margin-bottom: 10px;
    }
</style>
"""

html = f"""
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009-2019)</title>
    {css}
