                <div class="metric-value">{int(avg_reviews):,}</div>
                <div class="metric-label">Avg. Reviews per Book</div>
            </div>
            <div class="metric-card">
                <div class="metric-value">{genre_split['Non Fiction']}</div>
                <div class="metric-label">Non-Fiction Books</div>
            </div>
            <div class="metric-card">
                <div class="metric-value">{genre_split['Fiction']}</div>
                <div class="metric-label">Fiction Books</div>
            </div>
        </div>

