        <div class="chart-container">
            <img src="{scatter_img}" alt="Scatter Plot: Price vs. Rating">
        </div>

        <h2>3. Fiction vs. Non-Fiction: Pricing and Rating Strategies</h2>
        <table>
            <thead>
                <tr>
                    <th>Genre</th>
                    <th>Count</th>
                    <th>Average Price</th>
                    <th>Average Rating</th>
                    <th>Average Reviews</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td>{genre_stats.iloc[0]['Genre']}</td>
                    <td>{genre_stats.iloc[0]['Name']}</td>
                    <td>${genre_stats.iloc[0]['Price']:.2f}</td>
